-- An expression key whose type is an enum is four bytes whatever its label: `(COALESCE(e,
-- 'b'), text)` holds 2 688 characters over a 62-character label.
-- @setup
CREATE TYPE e AS ENUM ('b', 'llllllllllllllllllllllllllllllllllllllllllllllllllllllllllllll');
CREATE TABLE t (e e, c text);
CREATE INDEX t_i ON t ((COALESCE(e, 'b')), c);
INSERT INTO t VALUES ('llllllllllllllllllllllllllllllllllllllllllllllllllllllllllllll', '');
-- @test
-- @profile-lock
SELECT count(*) FROM t;
